import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import './Login.css';

function Login() {
  const [usuario, setUsuario] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    const result = await login(usuario, password);
    if (!result.success) {
      setError(result.error);
    }
    setLoading(false);
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <div className="logo-icon">
            <i className="fas fa-futbol"></i>
          </div>
          <h1>FútbolPro</h1>
          <p>Gestión Deportiva Profesional</p>
        </div>

        <form onSubmit={handleSubmit} className="login-form">
          <div className="input-group">
            <i className="fas fa-id-card"></i>
            <input
              type="text"
              placeholder="Usuario (Cédula / Identificación)"
              value={usuario}
              onChange={(e) => setUsuario(e.target.value)}
              required
              autoComplete="username"
            />
          </div>

          <div className="input-group">
            <i className="fas fa-lock"></i>
            <input
              type="password"
              placeholder="Contraseña"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              autoComplete="current-password"
            />
          </div>

          {error && <div className="error-message">{error}</div>}

          <button type="submit" className="login-btn" disabled={loading}>
            {loading ? <i className="fas fa-spinner fa-spin"></i> : 'Iniciar Sesión'}
          </button>
        </form>

        <div className="login-footer">
          <p className="creds-title">🔐 Credenciales de prueba:</p>
          <div className="test-creds">
            <div className="creds-item entrenador">
              <i className="fas fa-whistle"></i>
              <span><strong>Entrenador:</strong> ADMIN001 / 123456</span>
            </div>
            <div className="creds-info">
              <i className="fas fa-info-circle"></i>
              <small>Los jugadores reciben sus credenciales por correo al ser registrados</small>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Login;
